definition.script:
pipeline {
  agent any

  options {
    timestamps()
    disableConcurrentBuilds()
    buildDiscarder(logRotator(numToKeepStr: '30'))
  }

  stages {
    stage('Poll GitHub develop') {
      steps {
        sh '''#!/usr/bin/env bash
          set -euo pipefail
          # shellcheck source=/dev/null
          . /var/devops/jenkins/docker-lib.sh

          COL_ENV=/var/devops/collaboration/.env.docker
          HK_ENV=/var/devops/housekeeper/.env.docker

          COL_SRC="$(grep '^COLLABORATION_SOURCE=' "$COL_ENV" | cut -d= -f2-)"
          COL_BACK_BR="$(grep '^COLLABORATION_BACKEND_BRANCH=' "$COL_ENV" | cut -d= -f2- || echo develop)"
          COL_FE_BR="$(grep '^COLLABORATION_FRONTEND_BRANCH=' "$COL_ENV" | cut -d= -f2- || echo develop)"

          HK_SRC="$(grep '^HOUSEKEEPER_SOURCE=' "$HK_ENV" | cut -d= -f2-)"
          HK_BACK_BR="$(grep '^HOUSEKEEPER_BACKEND_BRANCH=' "$HK_ENV" | cut -d= -f2- || echo main)"
          HK_FE_BR="$(grep '^HOUSEKEEPER_FRONTEND_BRANCH=' "$HK_ENV" | cut -d= -f2- || echo main)"

          echo "=== GitHub change detected — rebuild only the repos that moved ==="

          poll_repo_and_trigger collaboration-backend "$COL_SRC/backend" "$COL_BACK_BR" collaboration-backend
          poll_repo_and_trigger collaboration-frontend "$COL_SRC/frontend" "$COL_FE_BR" collaboration-frontend
          poll_repo_and_trigger housekeeper-backend "$HK_SRC/backend" "$HK_BACK_BR" housekeeper-backend
          poll_repo_and_trigger housekeeper-frontend "$HK_SRC/frontend" "$HK_FE_BR" housekeeper-frontend

          echo "=== Poll done ==="
        '''
      }
    }
  }
}
